pub fn from_cow_str(cow: Cow<'_, str>) -> Cow<'_, RawStr> {
    match cow {
        Cow::Borrowed(s) => Cow::Borrowed(RawStr::new(s)),
        Cow::Owned(s) => Cow::Owned(RawStr::new(&s)),
    }
}

